y=dv_dt; s=np.sqrt(t)
fx={'1':np.ones_like(x),'x':x,'x2':x**2,'x3':x**3,'x15':x**1.5,'sqx':np.sqrt(x),'expx':np.exp(-x),'sinx':np.sin(x),'cosx':np.cos(x),'logx':np.log(x),'inv':1/x,'x2.5':x**2.5}
