ft={'1':np.ones_like(t),'t':t,'t2':t*t,'logt':np.log(t),'sqt':s,'expt':np.exp(-t),'cos_s':np.cos(s),'sin_s':np.sin(s),'inv':1/t,'cost':np.cos(t),'sint':np.sin(t)}
lib={}
for a,fa in fx.items():
  for b,fb in fv.items(): lib['x'+a+'*v'+b]=fa*fb
  for b,fb in ft.items(): lib['x'+a+'*t'+b]=fa*fb
for a,fa in fv.items():
  for b,fb in ft.items(): lib['v'+a+'*t'+b]=fa*fb
names=list(lib.keys())
M=np.column_stack([lib[n] for n in names])
